// q/a_general.js — Umumiy qoidalar, atamalar, piyodalar va yo'lovchilar (YHQ 1–5-boblar)

// ===================== GENERAL: hujjatlar (7-band) =====================
Q("general", "IIO xodimi talab qilganda mexanik transport vositasi haydovchisi qaysi hujjatlar to'plamini ko'rsatishi shart?",
  ["Haydovchilik guvohnomasi, texnik ko'rik talonchasi va fuqaro pasporti", "Ro'yxatdan o'tkazish guvohnomasi, tibbiy ma'lumotnoma va fuqaro pasporti", "Haydovchilik guvohnomasi, avtomaktab sertifikati va sug'urta polisi"],
  "Haydovchi tegishli toifadagi guvohnomani, transport vositasini (tirkama bo'lsa uni ham) ro'yxatdan o'tkazish guvohnomasini va majburiy sug'urta polisini yonida olib yurishi shart (YHQ 7-band).");
Q("general", "Majburiy fuqarolik javobgarligi sug'urta polisini qaysi ko'rinishda olib yurish mumkin?",
  ["Qog'oz yoki elektron ko'rinishda", "Faqat asl qog'oz nusxasida", "Faqat notarial tasdiqlangan nusxada", "Faqat sug'urta kompaniyasi muhri bilan"],
  "Qoidalarda sug'urta polisi «elektron ko'rinishda ham bo'lishi mumkin»ligi alohida ko'rsatilgan (YHQ 7-band).");
Q("general", "Haydovchilik guvohnomasi belgilangan tartibda olib qo'yilgan haydovchi transport vositasini boshqarishi uchun nimaga ega bo'lishi kerak?",
  ["Vaqtincha ruxsatnoma va shaxsini tasdiqlovchi hujjatga", "Guvohnoma nusxasi va sug'urta polisiga", "Faqat ichki ishlar organi ma'lumotnomasiga", "Vaqtincha ruxsatnoma va avtomaktab bitiruv guvohnomasiga"],
  "Guvohnoma olib qo'yilganda vaqtincha ruxsatnoma beriladi; u bilan boshqarishda haydovchi shaxsini tasdiqlovchi hujjatni ham olib yurishi kerak (YHQ 7-band).");
Q("general", "Sug'urta polisida (haydovchilar soni cheklangan) ko'rsatilgan bo'lsa, egasining qaysi qarindoshi alohida ishonchnomasiz uning avtomobilini boshqara oladi?",
  ["Egasining turmush o'rtog'i", "Egasining amakisi", "Egasining jiyani", "Egasining qaynotasi"],
  "Yaqin qarindoshlar — ota-ona, er (xotin), bolalar, aka-ukalar, opa-singillar; polisda ko'rsatilgan bo'lsa, ular ishonchnomasiz boshqarishi mumkin (YHQ 8-band).");
Q("general", "Qoidalarga ko'ra transport vositasi egasining «yaqin qarindoshlari» qatoriga kim KIRMAYDI?",
  ["Egasining tog'asi", "Egasining opa-singlisi", "Egasining otasi", "Egasining o'g'li"],
  "YHQ yaqin qarindoshlar ro'yxatini aniq belgilaydi: ota-ona, er (xotin), bolalar, aka-ukalar, opa-singillar; tog'a, amaki kabi boshqa qarindoshlar unga kirmaydi (YHQ 7-band).");
Q("general", "«Nogironligi bo'lgan shaxs» taniqlik belgisi o'rnatilgan avtomobilni I yoki II guruh nogironligi bo'lgan shaxs boshqarayotganda qo'shimcha qaysi hujjat bo'lishi kerak?",
  ["Nogironligini tasdiqlovchi hujjat", "Tibbiy-mehnat ekspertizasi yo'llanmasi", "Maxsus moslashtirilganlik dalolatnomasi", "Ijtimoiy himoya bo'limi ruxsatnomasi"],
  "Bunday taniqlik belgisi o'rnatilgan transport vositasini I yoki II guruh nogironligi bo'lgan shaxs boshqarayotganda nogironligini tasdiqlovchi hujjat bo'lishi shart (YHQ 7-band).");
Q("general", "Xorijiy avtotransport vositasi haydovchisi umumiy hujjatlardan tashqari qaysi hujjatni ham olib yurishi shart?",
  ["«Avtotransport vositasini qaytarib olib chiqish» majburiyatnomasi", "O'zbekistonda vaqtincha ro'yxatga olinganlik hujjati", "O'zbekiston avtomaktabida qayta o'qiganlik haqidagi ma'lumotnoma", "Xalqaro texnik ko'rikdan o'tganlik dalolatnomasi"],
  "Xorijiy avtotransport vositalari haydovchilari qo'shimcha ravishda «Avtotransport vositasini qaytarib olib chiqish to'g'risidagi majburiyatnoma»ni olib yuradi (YHQ 7-band).");
Q("general", "Haydovchi yonida biometrik pasporti yoki ID-kartasi bo'lsa ham, qaysi hujjatni ko'rsatishi talab etilishi mumkin?",
  ["Yuridik shaxs bergan yo'l varaqasi yoki yuk hujjatlari", "Haydovchilik guvohnomasining asl nusxasi", "Transport vositasini ro'yxatdan o'tkazish guvohnomasi", "Majburiy sug'urta polisining qog'oz nusxasi"],
  "ID-karta yoki biometrik pasport bo'lsa guvohnoma, ro'yxatdan o'tkazish guvohnomasi va polis planshetda tekshiriladi; ammo yuridik shaxs bergan ishonchnoma yoki yo'l varaqasi va yuk hujjatlari bundan mustasno (YHQ 7-band).");

// ===================== GENERAL: toifalar (8-band) =====================
Q("general", "Amaldagi tahrirdagi YHQ bo'yicha «A» toifasi qaysi transport vositalarini boshqarish huquqini beradi?",
  ["Mototsikl va elektromototsikllarni", "Mototsikl, moped va skuterlarni", "Mopedlar va kvadritsikllarni", "Mototsikl va yengil tirkamali avtomobillarni"],
  "2026-yil o'zgartirishidan so'ng «A» toifasi faqat mototsikllar va elektromototsikllarni o'z ichiga oladi; moped va skuterlar «A1» toifasiga o'tkazilgan (YHQ 8-band).");
Q("general", "Amaldagi tahrirdagi YHQ bo'yicha moped va skuterlarni boshqarish qaysi toifaga kiradi?",
  ["«A1»", "«A»", "«B»", "«BE»"],
  "«A1» toifasi — moped va skuterlar hamda kichik hajmdagi mototransport vositalari (individual harakatlanish vositalari bundan mustasno) (YHQ 8-band).");
Q("general", "«B» toifali avtomobilning ruxsat etilgan to'liq vazni qanchadan oshmasligi kerak?",
  ["3500 kg", "3000 kg", "3750 kg", "7500 kg"],
  "«B» toifasiga ruxsat etilgan to'liq vazni 3500 kilogrammdan oshmaydigan avtotransport vositalari kiradi (YHQ 8-band).");
Q("general", "«B» toifasidagi yo'lovchi avtomobilida haydovchi o'rindig'idan tashqari ko'pi bilan nechta o'rindiq bo'lishi mumkin?",
  ["8 ta", "6 ta", "9 ta", "12 ta"],
  "Haydovchi o'rindig'idan tashqari o'rindiqlar soni sakkiztadan ortiq bo'lmagan avtomobillar «B» toifasiga kiradi; ortig'i «D» toifasi (YHQ 8-band).");
Q("general", "«B» toifali guvohnoma bilan ruxsat etilgan to'liq vazni qanchadan oshmaydigan tirkamani alohida toifasiz tortish mumkin?",
  ["750 kg", "500 kg", "1000 kg", "1500 kg"],
  "Tirkamasining ruxsat etilgan to'liq vazni 750 kilogrammdan ortiq bo'lmagan «B» toifadagi avtomobillar «B» toifasiga kiradi; og'irroq tirkama uchun «BE» kerak (YHQ 8-band).");
Q("general", "Ruxsat etilgan to'liq vazni 5000 kg bo'lgan yuk avtomobilini (tirkamasiz) boshqarish uchun qaysi toifa kerak?",
  ["«C»", "«B»", "«CE»", "«D»"],
  "«C» toifasi — ruxsat etilgan to'liq vazni 3500 kilogrammdan ortiq avtotransport vositalari (YHQ 8-band).");
Q("general", "«C» toifali yuk avtomobili bilan ruxsat etilgan to'liq vazni 1200 kg bo'lgan tirkamani tortish uchun qaysi toifa kerak?",
  ["«CE»", "«C»", "«BE»", "«DE»"],
  "«C» toifasi faqat 750 kg gacha tirkama bilan cheklanadi; tirkamasi 750 kg dan og'ir «C» toifadagi avtomobillar uchun «CE» toifasi kerak (YHQ 8-band).");
Q("general", "Haydovchidan tashqari 16 ta o'rindiqli yo'lovchi avtobusini boshqarish uchun qaysi toifa kerak?",
  ["«D»", "«C»", "«B»", "«DE»"],
  "«D» — yo'lovchi tashishga mo'ljallangan, haydovchi o'rindig'idan tashqari o'rindiqlari sakkiztadan ortiq avtotransport vositalari (YHQ 8-band).");
Q("general", "Bo'g'imli (garmonli) avtobusni boshqarish uchun qaysi toifa talab qilinadi?",
  ["«DE»", "«D»", "«CE»", "«C»"],
  "«DE» toifasiga tirkamasi 750 kg dan og'ir «D» toifadagi avtomobillar hamda bo'g'imli avtobuslar kiradi (YHQ 8-band).");
Q("general", "«B» toifadagi yengil avtomobil bilan ruxsat etilgan to'liq vazni 750 kg dan ortiq tirkamani (tarkib 3500 kg dan oshmasa ham) tortish uchun qaysi toifa ko'zda tutilgan?",
  ["«BE»", "«B»", "«C»", "«CE»"],
  "«BE» toifasi tirkamasining ruxsat etilgan to'liq vazni 750 kg dan ortiq bo'lgan «B» toifadagi avtomobillarni qamraydi (YHQ 8-band).");
Q("general", "Trolleybus haydovchisi guvohnomasi bilan qaysi transport vositasini boshqarish mumkin?",
  ["Faqat trolleybusni", "Trolleybus va tramvayni", "Trolleybus va «D» toifali avtobusni", "Barcha shahar elektr transportini"],
  "Tramvay haydovchisiga faqat tramvay, trolleybus haydovchisiga faqat trolleybus boshqarishga ruxsat etiladi (YHQ 8-band).");
Q("general", "Sug'urta polisi cheklanmagan shaxslar uchun tuzilgan. Guvohnomasi bor do'stingiz egasiz va ishonchnomasiz sizning avtomobilingizni olib ketmoqchi. Qoidalar bo'yicha bu:",
  ["Mumkin emas: egasi yoki ishonchnoma egasi ishtirok etishi kerak", "Mumkin, chunki polis cheklanmagan shaxslar uchun tuzilgan", "Mumkin, agar egasi telefon orqali og'zaki rozilik bersa", "Mumkin, faqat aholi punkti chegarasidan chiqmasa"],
  "Begona transport vositasini faqat egasi yonida bo'lganda yoki ishonchnomasi bo'lgan shaxs ishtirokida (ularning roziligi bilan) boshqarish mumkin, bunda polis cheklanmagan bo'lishi yoki haydovchi polisda ko'rsatilgan bo'lishi kerak (YHQ 8-band).");
// ===================== GENERAL: yosh (149-band) =====================
